// port_interconnect_dut.v
//
// Hand-written gate-level fixture for the SDF `INTERCONNECT` reproducer
// (issue #250). NOT generated by place-and-route, and NOT part of the tile
// design -- see README.md in this directory.
//
// WHAT THIS ISOLATES
//
// Record measurements/timing-characterization/records/
// 20261017-sdf-sanitize-d811bcd.md Result 3 observed 28 of 179
// `INTERCONNECT` entries rejected by `$sdf_annotate`, every one of them
// sourced from a top-level input port bit, and left the cause un-isolated.
// The variable that actually decides it is the FANOUT of the source net,
// not the source's spelling: on a bit-selected top-level port net with
// physical fanout N, Icarus 13.0 can annotate exactly ONE destination and
// rejects the other N-1. Every section below exists to vary one thing at a
// time around that claim, so each case SDF in this directory annotates
// entries on a net whose fanout, source shape and destination kind are
// known by construction.
//
// DECLARATION ORDER IS LOAD-BEARING. The destination Icarus can annotate is
// the one belonging to the LAST-DECLARED instance on the net, so the order
// of the instantiations below is part of the fixture: reordering them moves
// which entry is accepted and invalidates the expectation table in run.sh.
// Each group is declared in `u_<x>0 .. u_<x>3` order and the expectation
// table names `u_<x>3` (or the group's last member) as the survivor.
//
// Why real `sky130_fd_sc_hd` cells: the destination pins of the real
// rejected entries are standard-cell pins carrying `specify`/`IOPATH`
// blocks (1664 `specify` blocks in the pinned library), and a hand-written
// stand-in risks omitting whatever makes the failure appear. The ONE
// stand-in here, `nospec_sink`, is deliberately specify-free and is used
// only by the control that tests whether `specify` matters at all.
//
// Port shapes mirror the committed logic_tile SDF
// (measurements/timing-characterization/logic_tile_route.sdf): `in` is a
// BUS, so `in[N]` is a bit-selected top-level port (113 of its 179 entries
// are sourced from one); `clk` is a SCALAR top-level port.

`default_nettype none

// Control sink with NO `specify` block of any kind. Used only by the
// `fanout2_bitsel_nospecify` case, to test the precondition
// klayout-tools#1619 shape (b) states for the failure ("fails whenever its
// destination pin declares its own specify/IOPATH block").
module nospec_sink (
    output wire Y,
    input  wire A
);
    assign Y = ~A;
endmodule

module port_interconnect_dut (
    in,
    clk,
    out
);
    // Bit-selected (bus) top-level input port bits, each with a different,
    // deliberately chosen fanout -- see the group comments below.
    input  wire [5:0] in;
    // Scalar top-level input port. Fanout 4, mirroring the committed SDF's
    // `rst` net (4 entries, all applied in the record's run).
    input  wire       clk;
    output wire [19:0] out;

    wire a0, a1, a2, a3;    // in[0], bit-selected port, fanout 4
    wire b0, b1;            // in[1], bit-selected port, fanout 2
    wire c0;                // in[2], bit-selected port, fanout 1
    wire n0, n1;            // in[3], bit-selected port, fanout 2, no-specify sinks
    wire m0;                // in[4], bit-selected port, fanout 1, mux4_1
    wire buf_x;             // in[5] -> u_buf.X, the buffer remedy
    wire e0, e1;            // u_buf.X, instance-pin source, fanout 2
    wire s0, s1, s2, s3;    // clk, scalar port, fanout 4
    wire p0, p1, p2, p3;    // u_a3.X, instance-pin source, fanout 4

    // ------------------------------------------------------------------ //
    // GROUP A -- `in[0]`: bit-selected port net, physical fanout 4.
    // The shape of the committed SDF's 8 four-way `in[N]` nets (32 of its
    // 40 `in[N]` entries). Expect 1 of 4 annotatable: `u_a3.S0`.
    // Select is {S1,S0} = {0,in[0]} with A0/A1 = 0/1, so each X tracks
    // in[0] and an applied interconnect delay is directly observable.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__mux4_2 u_a0 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[0]), .S1 (1'b0), .X (a0)
    );
    sky130_fd_sc_hd__mux4_2 u_a1 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[0]), .S1 (1'b0), .X (a1)
    );
    sky130_fd_sc_hd__mux4_2 u_a2 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[0]), .S1 (1'b0), .X (a2)
    );
    sky130_fd_sc_hd__mux4_2 u_a3 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[0]), .S1 (1'b0), .X (a3)
    );

    // ------------------------------------------------------------------ //
    // GROUP B -- `in[1]`: bit-selected port net, physical fanout 2.
    // The shape of the committed SDF's 4 two-way `ce[N]` nets (8 entries).
    // Expect 1 of 2 annotatable: `u_b1.S0`.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__mux4_2 u_b0 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[1]), .S1 (1'b0), .X (b0)
    );
    sky130_fd_sc_hd__mux4_2 u_b1 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[1]), .S1 (1'b0), .X (b1)
    );

    // ------------------------------------------------------------------ //
    // GROUP C -- `in[2]`: bit-selected port net, physical fanout 1.
    // THE DISCRIMINATOR. Same source spelling and same specify-bearing
    // destination pin as GROUP A, differing only in fanout. The shape of
    // the committed SDF's 8 one-way `in[N]` nets, its 64 `lut_init[N]` and
    // its 4 `reg_sel[N]` nets -- 113 of 179 entries. Expect APPLIED.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__mux4_2 u_c0 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (in[2]), .S1 (1'b0), .X (c0)
    );

    // ------------------------------------------------------------------ //
    // GROUP N -- `in[3]`: bit-selected port net, fanout 2, destinations
    // with NO `specify` block. Control for shape (b)'s stated precondition.
    // Expect the same 1-of-2 outcome as GROUP B if `specify` is irrelevant.
    // ------------------------------------------------------------------ //
    nospec_sink u_n0 (.A (in[3]), .Y (n0));
    nospec_sink u_n1 (.A (in[3]), .Y (n1));

    // ------------------------------------------------------------------ //
    // GROUP M -- `in[4]`: bit-selected port net, fanout 1, on `mux4_1`,
    // the cell issue #250's acceptance criteria name. (The committed SDF's
    // own bit-selected-port entries land on `mux4_2`; the two cells have
    // the same pin set and the same `specify` shape.) Expect APPLIED.
    // Select {S1,S0} = {in[4],0} with A0/A2 = 0/1.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__mux4_1 u_m0 (
        .A0 (1'b0), .A1 (1'b0), .A2 (1'b1), .A3 (1'b0),
        .S0 (1'b0), .S1 (in[4]), .X (m0)
    );

    // ------------------------------------------------------------------ //
    // GROUP E -- the BUFFER REMEDY. `in[5]` reaches u_e0/u_e1 only through
    // u_buf, so the annotated entries' SOURCE is a cell output pin at
    // fanout 2 instead of a port bit at fanout 2. This is the half of issue
    // #250's suggested remedy that upstream's wrapper finding does not rule
    // out. Expect BOTH entries applied, which is the whole point.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__buf_1 u_buf (.A (in[5]), .X (buf_x));
    sky130_fd_sc_hd__mux4_2 u_e0 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (buf_x), .S1 (1'b0), .X (e0)
    );
    sky130_fd_sc_hd__mux4_2 u_e1 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (buf_x), .S1 (1'b0), .X (e1)
    );

    // ------------------------------------------------------------------ //
    // GROUP S -- `clk`: SCALAR top-level port net, physical fanout 4.
    // The shape of the committed SDF's `rst` net. Expect ALL 4 applied,
    // which is what makes this a fanout-plus-bit-select effect rather than
    // a fanout effect.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__mux4_2 u_s0 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (clk), .S1 (1'b0), .X (s0)
    );
    sky130_fd_sc_hd__mux4_2 u_s1 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (clk), .S1 (1'b0), .X (s1)
    );
    sky130_fd_sc_hd__mux4_2 u_s2 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (clk), .S1 (1'b0), .X (s2)
    );
    sky130_fd_sc_hd__mux4_2 u_s3 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (clk), .S1 (1'b0), .X (s3)
    );

    // ------------------------------------------------------------------ //
    // GROUP P -- `u_a3.X`: INSTANCE-PIN source net, physical fanout 4.
    // The positive control, and the shape of the committed SDF's 58
    // instance-pin entries. Expect ALL 4 applied.
    // ------------------------------------------------------------------ //
    sky130_fd_sc_hd__mux4_2 u_p0 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (a3), .S1 (1'b0), .X (p0)
    );
    sky130_fd_sc_hd__mux4_2 u_p1 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (a3), .S1 (1'b0), .X (p1)
    );
    sky130_fd_sc_hd__mux4_2 u_p2 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (a3), .S1 (1'b0), .X (p2)
    );
    sky130_fd_sc_hd__mux4_2 u_p3 (
        .A0 (1'b0), .A1 (1'b1), .A2 (1'b0), .A3 (1'b0),
        .S0 (a3), .S1 (1'b0), .X (p3)
    );

    assign out = {p3, p2, p1, p0,
                  s3, s2, s1, s0,
                  e1, e0,
                  m0,
                  n1, n0,
                  c0,
                  b1, b0,
                  a3, a2, a1, a0};

endmodule

`default_nettype wire
